CREATE OR REPLACE FUNCTION public.admin_get_business_billing(p_owner_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO public AS $$ BEGIN IF NOT has_role(auth.uid(),'super_admin'::app_role) THEN RAISE EXCEPTION 'Not authorized'; END IF; RETURN compute_business_billing(p_owner_id); END $$; GRANT EXECUTE ON FUNCTION public.admin_get_business_billing(uuid) TO authenticated, service_role;